INSERT INTO settings (key,value,updated_at) VALUES
 ('kudos','{"levels":[{"name":"Appreciation","points":1},{"name":"Impact","points":2},{"name":"Exceptional","points":3},{"name":"Legendary","points":5}],"categories":[{"name":"Teamwork","icon":"handshake","art":["creative-buddy.png","imagination.png"],"prompts":["You made the whole sprint feel lighter - thanks for pairing on the tricky bits without ever being asked.","When the deadline moved up, you pulled everyone together instead of panicking. That''s the glue this team runs on.","Thanks for looping in QA early and keeping design in sync - the handoff was the smoothest we''ve had.","You never say \"not my job\". Every time someone''s stuck, you''re already in the thread helping.","The way you shared credit in the demo said everything about how you work. Grateful to be on your team."]},{"name":"Innovation","icon":"lightbulb","art":["out-of-the-box.png","brain-storming.png"],"prompts":["Your \"what if we just...\" idea in standup cut a two-week task down to two days. Brilliant.","You questioned an assumption everyone else had accepted for years - and you were right.","The prototype you hacked together over lunch became the plan of record. That''s how change starts here.","Thanks for trying the unconventional route when the safe one kept failing. It paid off big.","You didn''t just spot the problem - you brought three ways to fix it. That mindset is contagious."]},{"name":"Customer Focus","icon":"heart","art":["i-heart-design.png","think-about.png"],"prompts":["You stayed on that support call until the customer was genuinely unblocked, not just handed off. They noticed - so did we.","The way you translated the client''s vague ask into exactly what they needed was masterful.","You fought for the user in that roadmap debate, and the product is better for it.","Thanks for following up with the customer a week later just to make sure the fix stuck. That''s rare.","You turned an angry escalation into a renewal. Enough said."]},{"name":"Ownership","icon":"shield-check","art":["hard-work.png","tidy-up.png"],"prompts":["You saw the incident, took the lead, and drove it to resolution before anyone even assigned it. Textbook ownership.","\"I''ll take that\" might be your catchphrase - and you always follow through.","You owned the miss in the retro without excuses, then fixed the process so it can''t happen again. Huge respect.","The migration nobody wanted to touch? You quietly finished it. Thank you.","You treat every corner of this product like your name is on it. Because of you, it shows."]},{"name":"Excellence","icon":"award","art":["embrace-your-perfection.png","you-did-it.png"],"prompts":["Your PRs are the ones people open just to learn from. The bar you set lifts everyone.","Zero defects, ahead of schedule, documented to perfection. That release was a masterclass.","You sweat the details nobody sees - and it''s exactly why everything you ship feels solid.","The report you put together was so thorough leadership reused it verbatim. Outstanding work.","Quality isn''t a phase for you, it''s a habit. This month proved it again."]},{"name":"Leadership","icon":"crown","art":["ready-set-go.png","thinking-out-loud.png"],"prompts":["You didn''t need the title to lead - the room naturally turned to you, and you delivered.","Thanks for shielding the team from the noise so we could focus. That''s real leadership.","The way you coached the new joiner through their first release doubled their confidence.","You made the hard call, explained it honestly, and carried the team through it. That earned trust.","In the toughest week of the quarter, your calm set the tone for everyone."]},{"name":"Going the Extra Mile","icon":"rocket","art":["explore-new-world.png","focus-time.png"],"prompts":["You stayed late to get the demo across the line - and never once made it feel like a favor.","That fix you shipped on Saturday saved Monday for the whole team. Thank you.","You didn''t stop at the fix - you wrote the runbook, added alerts, and closed the loop for good.","Way beyond the ask, way ahead of the deadline. You went above and beyond, again.","Nobody would have blamed you for stopping at \"good enough\". You didn''t. It shows."]},{"name":"Helping Hand","icon":"hand-heart","art":["coffee-time.png","good-job.png"],"prompts":["You dropped your own work to unblock mine, twice this week. I owe you one - or five.","Thanks for the patient walkthrough of the deploy pipeline. You turned my worst day into a learning day.","New folks always land on their feet here - mostly because you''re the first to offer help.","That 11pm \"need a hand?\" message meant more than you know.","You answer every question like it''s a great question. It makes people brave enough to ask."]},{"name":"Learning & Growth","icon":"book-open","art":["open-mind.png","creative-mind.png"],"prompts":["You picked up a whole new stack in three weeks and shipped with it. Seriously impressive.","The lunch-and-learn you ran had the whole team taking notes. Teach us more!","You took the feedback from last cycle and visibly turned it into strength. That takes real character.","Watching you grow from asking the questions to answering them has been the best part of this quarter.","You turned your certification study into shared notes for everyone. Learning, multiplied."]},{"name":"Positivity","icon":"smile","art":["relax-time.png","drawing.png"],"prompts":["Even when the build was red and the coffee machine died, you kept the team laughing. Priceless.","Your energy in Monday standups genuinely sets up the whole week.","Thanks for celebrating the small wins - you make progress feel like progress.","You find the silver lining in every incident review, and somehow it always turns into an action item.","The team is measurably happier when you''re in the room. Never change."]}]}',1700000000000);
INSERT INTO letter_templates (uuid,code,label,category,filename,inputs,blocks,created_at,updated_at) VALUES
 ('00000000009rg','01','Offer Letter','Onboarding','{{employee_name}} - Offer Letter',NULL,'[{"kind":"subject","text":"Subject: Offer of Employment"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"Congratulations!","bold":true},{"kind":"para","text":"Further to our discussions and the selection process, **{{company}}** (the \"Company\") is pleased to extend to you this offer of employment on the terms and conditions set out below. We were impressed by your background and believe you will make a valuable contribution to the Company."},{"kind":"para","text":"We are pleased to offer you a full-time {{work_mode}} position as **{{designation}}**{{department_clause}}{{reporting_to_clause}}. Your scheduled start date will be **{{joining_date}}**.{{probation_clause}}"},{"kind":"para","text":"Your normal working hours will be **{{working_pattern}}**{{work_location_suffix}}. The Company may, at its sole discretion and in the interests of the business, vary your role, duties, reporting line, place of work and hours from time to time.","requires":"working_pattern"},{"kind":"para","text":"The remuneration offered to you is an annual cost to company (CTC) of **{{ctc_in_words}}**, on which professional tax, income tax and other statutory deductions apply at the rates in force. The detailed breakup is set out in the **Salary Annexure** to this letter. Your remuneration is strictly confidential and is not to be disclosed to any other employee or third party.","requires":"ctc"},{"kind":"para","text":"This offer is made subject to, and is conditional upon, the following:","bold":true},{"kind":"bullets","items":["Satisfactory completion of reference, employment, education, identity and, where applicable, background and criminal-record verification. The Company reserves the right, at its sole discretion, to withdraw this offer or to terminate your employment at any time if any information or document furnished by you is found to be false, misleading or incomplete.","Your execution of the Company''s Non-Disclosure, Non-Solicitation and Invention Assignment Agreement, and your continued compliance with all policies, codes and rules of the Company as amended from time to time.","Your being, and remaining, legally eligible to work and fit to perform the duties of the role, subject to any reasonable accommodation required by applicable law.","This being a letter of intent to offer employment. The binding Appointment Letter, setting out the full terms and conditions of your employment, will be issued to you on your date of joining and shall govern the employment relationship."]},{"kind":"para","text":"During your employment you shall devote your whole time, attention and abilities to the business of the Company, shall not engage in any other trade, business, employment or consultancy without the Company''s prior written consent, and shall not solicit its employees, customers or suppliers. You shall keep all confidential and proprietary information of the Company strictly confidential both during and after your employment, and all work product and intellectual property created by you in the course of your employment shall vest solely in the Company. To the extent permitted by applicable law, you authorise the Company to recover and set off any amount lawfully due from you - including notice-pay shortfall, advances, loans and the value of any unreturned Company property - against any amount payable to you."},{"kind":"para","text":"Joining Formalities:","bold":true},{"kind":"para","text":"Please submit the following documents at the time of your joining:"},{"kind":"bullets","items":["Signed copy of this offer letter","Educational qualification: marksheets and certificates of 10th, 12th, Graduation & Post Graduation (if any)","Relieving / resignation acceptance letter from present / previous employer","Documentary evidence of last salary drawn (payslips of last 3 months & Form 16)","One passport-size colour photograph","PAN Card","Aadhaar Card"]},{"kind":"para","text":"This offer is valid until **{{validity_date}}**. Please confirm your acceptance by signing below on or before that date, after which this offer stands automatically withdrawn without further notice.","requires":"validity_date"},{"kind":"para","text":"This letter, together with the documents referred to in it, constitutes the entire understanding between you and the Company in relation to this offer and supersedes all prior discussions, representations and correspondence, until superseded by the Appointment Letter. It may be varied only in writing signed by an authorized representative of the Company. If any provision is held invalid or unenforceable, the remaining provisions shall continue in full force. This letter is governed by the laws of India, with the courts at the Company''s registered office having exclusive jurisdiction."},{"kind":"para","text":"We look forward to welcoming you to **{{company}}**. Should you have any questions, please reach out{{hr_contact_clause}} at your earliest convenience."},{"kind":"signature","closing":"For and on behalf of {{company}},"},{"kind":"gap","height":10},{"kind":"subject","text":"Acceptance and Declaration by the Employee"},{"kind":"para","text":"I, **{{legal_name}}**, have read and understood this offer of employment in its entirety and I accept it unconditionally. I confirm that the information and documents furnished by me to the Company are true, complete and accurate, and I consent to their verification and to the collection and processing of my personal data by the Company for employment and statutory purposes. I agree to be bound by the terms of this letter, the Appointment Letter to be issued to me, and all policies of the Company as amended from time to time. I agree that this document may be executed electronically, and that my acceptance and signature provided by electronic means are valid, binding and enforceable on me."},{"kind":"esignature","label":"Employee Signature","withDate":true},{"kind":"pageBreak","requires":"ctc"},{"kind":"subject","text":"Salary Annexure","requires":"ctc"},{"kind":"computed","ref":"ctc_annexure","requires":"ctc"},{"kind":"note","text":"NOTE: Net pay does not include taxes or other deductions (if any). The compensation package is subject to all applicable tax laws currently in force.","requires":"ctc"}]',1700000000000,1700000000000),
 ('00000000009rj','02','Appointment Letter','Onboarding','{{employee_name}} - Appointment Letter',NULL,'[{"kind":"subject","text":"Subject: Letter of Appointment"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"With reference to your application and the subsequent selection process, **{{company}}** (the \"Company\") is pleased to appoint you as **{{designation}}**{{department_clause}}{{reporting_to_clause}}, with effect from **{{joining_date}}**.{{probation_clause}} Your appointment is governed by the terms and conditions set out below."},{"kind":"para","text":"Your annual cost to company (CTC) is **{{ctc_in_words}}**, on which professional tax, income tax and other statutory deductions apply at the rates in force. The detailed breakup is provided in the **Salary Annexure**. Your remuneration is confidential and personal to you, and is subject to periodic review entirely at the discretion of the Company; a review does not imply or guarantee any increase.","requires":"ctc"},{"kind":"para","text":"Your normal working hours will be **{{working_pattern}}**{{work_location_suffix}}.","requires":"working_pattern"},{"kind":"para","text":"Terms and Conditions of Employment:","bold":true},{"kind":"bullets","items":["Duties and exclusivity: You shall diligently discharge the duties assigned to you and such other duties as the Company may reasonably require, shall devote your whole time and attention to the Company''s business, and shall not, during your employment, engage in any other trade, business, employment or consultancy without the Company''s prior written consent.","Place of work and mobility: You may be required, at the sole discretion of the Company, to work at, or be transferred or deputed to, any of its offices, group companies, clients or locations, whether in India or abroad, without diminution of your remuneration.","Policies and conduct: Your employment is at all times governed by, and you shall comply with, the policies, codes of conduct and rules of the Company as amended from time to time, which form part of these terms.","Confidentiality and intellectual property: You shall keep all confidential and proprietary information of the Company strictly confidential both during and after your employment. All work product, inventions and intellectual property created by you in the course of your employment shall vest solely and exclusively in the Company.","Non-solicitation and conflict of interest: During your employment and, to the extent permitted by applicable law, for twelve (12) months thereafter, you shall not solicit or entice away any employee, customer or supplier of the Company, and you shall promptly disclose and avoid any actual or potential conflict of interest.","Probation and confirmation: Confirmation of your employment is at the sole discretion of the Company upon satisfactory performance; until confirmed in writing, you remain on probation, which the Company may extend.","Termination and notice: After confirmation, either party may terminate this employment by serving the notice period stipulated in Company policy, or salary in lieu thereof. In the event of proven misconduct or material breach of these terms, the Company may, following the process required by applicable law and Company policy, terminate your employment without notice or pay in lieu. Nothing in this clause limits the protections available to you under applicable law.","Fitness and accuracy: This appointment is conditional on the accuracy of the documents and information furnished by you and on your fitness to perform the duties of the role, subject to any reasonable accommodation and protection required by applicable law; any misrepresentation by you renders this appointment liable to termination.","Recovery and set-off: To the extent permitted by applicable law, you authorise the Company to recover and set off any amount lawfully due from you - including notice-pay shortfall, advances, loans and the value of unreturned Company property - against any amount payable to you, including your full and final settlement.","Retirement: You shall retire from the services of the Company on attaining the age of superannuation as per Company policy.","Severability and survival: If any provision of these terms is held invalid or unenforceable, it shall be modified to the minimum extent necessary, or severed, and the remaining provisions shall continue in full force. Your obligations relating to confidentiality, intellectual property, non-solicitation and return of Company property survive the termination of your employment."]},{"kind":"para","text":"This letter, together with the Company''s policies and the Salary Annexure, constitutes the entire agreement between you and the Company and supersedes all prior offers, discussions and representations. It may be varied only in writing signed by an authorized representative of the Company, and is governed by the laws of India, with the courts at the Company''s registered office having exclusive jurisdiction."},{"kind":"para","text":"We welcome you to **{{company}}** and look forward to a long and mutually rewarding association."},{"kind":"signature","closing":"For and on behalf of {{company}},"},{"kind":"gap","height":10},{"kind":"subject","text":"Acceptance and Declaration by the Employee"},{"kind":"para","text":"I, **{{legal_name}}**, have read, understood and accept this Letter of Appointment and all the terms and conditions set out in it and in the Company''s policies. I confirm that the information and documents furnished by me are true, complete and accurate, and I consent to the collection and processing of my personal data by the Company for employment and statutory purposes. I agree to be bound by these terms during my employment with the Company. I agree that this document may be executed electronically, and that my acceptance and signature provided by electronic means are valid, binding and enforceable on me."},{"kind":"esignature","label":"Employee Signature","withDate":true},{"kind":"pageBreak","requires":"ctc"},{"kind":"subject","text":"Salary Annexure","requires":"ctc"},{"kind":"computed","ref":"ctc_annexure","requires":"ctc"},{"kind":"note","text":"NOTE: Net pay does not include taxes or other deductions (if any). The compensation package is subject to all applicable tax laws currently in force.","requires":"ctc"}]',1700000000000,1700000000000),
 ('00000000009rm','03','Confirmation Letter','Onboarding','{{employee_name}} - Confirmation Letter',NULL,'[{"kind":"subject","text":"Subject: Confirmation of Employment"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"We are pleased to confirm your employment with **{{company}}** as **{{designation}}**{{department_clause}}, with effect from **{{joining_date}}**, following the successful completion of your probationary period."},{"kind":"para","text":"Your current annual CTC is **{{ctc_in_words}}**.","requires":"ctc"},{"kind":"para","text":"All the terms and conditions of your employment, including those relating to confidentiality, intellectual property, non-solicitation and notice, as set out in your Letter of Appointment and the Company''s policies, continue to apply and remain in full force. We congratulate you and look forward to your continued contribution."},{"kind":"signature","closing":"For and on behalf of {{company}},"}]',1700000000000,1700000000000),
 ('00000000009rp','04','Probation Extension Letter','Onboarding','{{employee_name}} - Probation Extension',NULL,'[{"kind":"subject","text":"Subject: Extension of Probation"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"This is with reference to your employment with **{{company}}** as **{{designation}}**{{department_clause}}, which commenced on **{{joining_date}}**."},{"kind":"para","text":"After a review of your performance during the probationary period, the Company has decided to extend your probation. During the extended period, your performance will be reviewed again, and at the end of it the Company reserves the right, at its sole discretion and in accordance with applicable law, to confirm your employment, further extend your probation, or terminate your employment."},{"kind":"para","text":"All other terms and conditions of your employment remain unchanged and in full force. We encourage you to use this period to demonstrate the improvements discussed with you."},{"kind":"signature","closing":"For and on behalf of {{company}},"}]',1700000000000,1700000000000),
 ('00000000009rr','05','Confidentiality & IP Assignment Agreement','Agreements','{{employee_name}} - Confidentiality and IP Assignment Agreement',NULL,'[{"kind":"subject","text":"Subject: Non-Disclosure, Non-Solicitation and Invention Assignment Agreement"},{"kind":"para","text":"This Agreement is entered into between **{{company}}** (the \"Company\") and **{{legal_name}}** (the \"Employee\"){{exp_designation_clause}}, and forms part of, and is a condition of, the Employee''s employment with the Company."},{"kind":"para","text":"1. Confidentiality.","bold":true},{"kind":"para","text":"The Employee acknowledges that in the course of employment the Employee will have access to confidential and proprietary information of the Company, including business plans, customer and supplier data, pricing, source code, trade secrets, financial and personnel information (\"Confidential Information\"). The Employee shall hold all Confidential Information in strict confidence, shall use it solely for the Company''s benefit and in the discharge of assigned duties, and shall not disclose it to any third party, both during employment and at all times after its cessation. This obligation does not apply to information that is or becomes publicly available other than through the Employee''s breach, or that the Employee is required to disclose by law or court or regulatory order, provided the Employee gives the Company prompt prior notice where lawfully permitted."},{"kind":"para","text":"2. Assignment of Intellectual Property.","bold":true},{"kind":"para","text":"All inventions, works, discoveries, designs, software and other intellectual property conceived, developed or reduced to practice by the Employee, whether alone or with others, in the course of or in connection with the employment, shall be the sole and exclusive property of the Company. The Employee hereby irrevocably assigns all right, title and interest in such intellectual property to the Company and agrees to execute all documents and do all acts necessary to perfect and protect the Company''s rights, both during and after employment."},{"kind":"para","text":"3. Non-Solicitation.","bold":true},{"kind":"para","text":"During employment and, to the extent permitted by applicable law, for a period of twelve (12) months following its cessation, the Employee shall not, directly or indirectly, solicit, entice away or endeavour to engage any employee, consultant, customer or supplier of the Company, nor interfere with the Company''s business relationships. Nothing in this Agreement restrains the Employee from lawfully exercising a profession, trade or business after the cessation of employment."},{"kind":"para","text":"4. Return of Property.","bold":true},{"kind":"para","text":"On cessation of employment, or earlier on the Company''s request, the Employee shall return all Company property, documents and Confidential Information (in every form and copy) in the Employee''s possession or control, and shall retain no copies."},{"kind":"para","text":"5. Remedies and General.","bold":true},{"kind":"para","text":"The Employee acknowledges that any breach of this Agreement would cause the Company irreparable harm for which damages alone would be inadequate, and that the Company shall be entitled to injunctive relief in addition to any other remedy. This Agreement survives the termination of employment, is in addition to the Employee''s obligations under the Letter of Appointment and Company policy, is governed by the laws of India, and is subject to the exclusive jurisdiction of the courts at the Company''s registered office. If any provision is held unenforceable, the remainder shall continue in full force."},{"kind":"para","text":"The Employee confirms that the Employee has read and understood this Agreement and agrees to be bound by it. The Employee agrees that this Agreement may be executed electronically, and that a signature provided by electronic means is valid, binding and enforceable."},{"kind":"gap","height":6},{"kind":"para","text":"Signed for and on behalf of the Company:"},{"kind":"signature","closing":"For and on behalf of {{company}},"},{"kind":"gap","height":10},{"kind":"para","text":"Agreed and accepted by the Employee:"},{"kind":"esignature","label":"Employee Signature","withDate":true}]',1700000000000,1700000000000);
INSERT INTO letter_templates (uuid,code,label,category,filename,inputs,blocks,created_at,updated_at) VALUES
 ('00000000009rt','06','Promotion Letter','Career','{{employee_name}} - Promotion Letter',NULL,'[{"kind":"subject","text":"Subject: Promotion"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"We are pleased to inform you that, in recognition of your performance and contribution, you have been promoted from **{{old_designation}}** to **{{new_designation}}**, effective **{{role_effective_date}}**.","requires":"promotion"},{"kind":"para","text":"Your new role and responsibilities will be communicated to you by your reporting manager. All other terms and conditions of your employment remain unchanged."},{"kind":"para","text":"We congratulate you on this well-deserved recognition and look forward to your continued contribution."},{"kind":"signature","closing":"Best regards,"}]',1700000000000,1700000000000),
 ('00000000009rw','07','Transfer Letter','Career','{{employee_name}} - Transfer Letter',NULL,'[{"kind":"subject","text":"Subject: Transfer"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"This is to inform you that you are being transferred {{transfer_clause}}, effective **{{role_effective_date}}**.","requires":"transfer"},{"kind":"para","text":"Your terms of employment remain unchanged except as stated above. We request you to coordinate with your reporting manager for a smooth transition of your responsibilities."},{"kind":"para","text":"We wish you continued success in your new assignment."},{"kind":"signature","closing":"For {{company}},"}]',1700000000000,1700000000000),
 ('00000000009ry','08','Increment Letter','Compensation','{{employee_name}} - Increment Letter',NULL,'[{"kind":"subject","text":"Subject: Revision in Compensation"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"We are pleased to inform you that, in recognition of your performance and contribution, your compensation has been revised."},{"kind":"para","text":"Your revised annual CTC will be **{{inc_new_annual_words}}**, effective **{{inc_effective_date}}**.","requires":"increment"},{"kind":"computed","ref":"increment_table","requires":"increment"},{"kind":"para","text":"Your annual CTC is **{{ctc_in_words}}**, effective **{{date}}**.","requires":"ctc_no_increment"},{"kind":"para","text":"This revision is made at the sole discretion of the Company and does not create any entitlement to, or expectation of, any future revision. Your revised remuneration is confidential and personal to you. All other terms and conditions of your employment remain unchanged and in full force. We thank you for your continued commitment and look forward to your ongoing contribution."},{"kind":"signature","closing":"For and on behalf of {{company}},"}]',1700000000000,1700000000000),
 ('00000000009s0','09','Appraisal Letter','Compensation','{{employee_name}} - Appraisal Letter',NULL,'[{"kind":"subject","text":"Subject: Performance Appraisal"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"We would like to acknowledge and appreciate your performance and contribution {{appraisal_role_clause}} over the appraisal period. Your dedication and commitment have been valuable to the organization."},{"kind":"para","text":"Following your appraisal, your annual CTC has been revised to **{{inc_new_annual_words}}**, effective **{{inc_effective_date}}**. A detailed compensation breakup is available with the HR team.","requires":"increment"},{"kind":"para","text":"Your current annual CTC stands at **{{ctc_in_words}}**. A detailed compensation breakup is available with the HR team.","requires":"ctc_no_increment"},{"kind":"para","text":"Any revision reflected above is made at the sole discretion of the Company and confers no entitlement to future revisions. All other terms and conditions of your employment remain unchanged. We look forward to your continued growth and success with us, and we are confident that you will keep raising the bar in the period ahead."},{"kind":"signature","closing":"For and on behalf of {{company}},"}]',1700000000000,1700000000000),
 ('00000000009s2','10','Bonus / Incentive Letter','Compensation','{{employee_name}} - {{bonus_kind}}',NULL,'[{"kind":"subject","text":"Subject: {{bonus_kind}}"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"We are pleased to inform you that you have been awarded a {{bonus_kind}} of **{{bonus_amount_words}}**, with effect from **{{bonus_date}}**.{{bonus_reason_clause}}","requires":"bonus"},{"kind":"para","text":"The amount will be processed as per company policy, subject to applicable statutory deductions."},{"kind":"para","text":"We thank you for your efforts and look forward to your continued contribution."},{"kind":"signature","closing":"Best regards,"}]',1700000000000,1700000000000);
INSERT INTO letter_templates (uuid,code,label,category,filename,inputs,blocks,created_at,updated_at) VALUES
 ('00000000009s4','11','Salary Certificate','Compensation','{{employee_name}} - Salary Certificate',NULL,'[{"kind":"subject","text":"Subject: Salary Certificate"},{"kind":"para","text":"To Whomsoever It May Concern,"},{"kind":"para","text":"This is to certify that **{{employee_name}}** is employed with **{{company}}**{{exp_designation_clause}}{{exp_department_clause}} since **{{joining_date}}**."},{"kind":"para","text":"The current annual cost to company (CTC) is **{{ctc_in_words}}**. The detailed breakup is provided below.","requires":"ctc"},{"kind":"computed","ref":"ctc_annexure","requires":"ctc"},{"kind":"para","text":"This certificate is issued on request for the employee''s records and may be used for official purposes."},{"kind":"signature","closing":"For {{company}},"}]',1700000000000,1700000000000),
 ('00000000009s6','12','Employment Verification','Verification','{{employee_name}} - Employment Verification',NULL,'[{"kind":"subject","text":"Subject: Employment Verification"},{"kind":"para","text":"To Whomsoever It May Concern,"},{"kind":"para","text":"This is to certify that **{{employee_name}}** is currently employed with **{{company}}**{{exp_designation_clause}}{{exp_department_clause}}, and has been with the organization since **{{joining_date}}**."},{"kind":"para","text":"This letter is issued at the request of the employee for the purpose of verification of employment. Should you require any further information, please contact us{{hr_contact_clause}}."},{"kind":"signature","closing":"For {{company}},"}]',1700000000000,1700000000000),
 ('00000000009s8','13','No Objection Certificate','Verification','{{employee_name}} - No Objection Certificate',NULL,'[{"kind":"subject","text":"Subject: No Objection Certificate"},{"kind":"para","text":"To Whomsoever It May Concern,"},{"kind":"para","text":"This is to certify that **{{employee_name}}** is employed with **{{company}}**{{exp_designation_clause}}{{exp_department_clause}} since **{{joining_date}}**."},{"kind":"para","text":"The organization has **no objection** to the employee''s application and confirms that there is no impediment from our side. We extend our support for the purpose for which this certificate has been requested."},{"kind":"para","text":"This certificate is issued on the employee''s request."},{"kind":"signature","closing":"For {{company}},"}]',1700000000000,1700000000000),
 ('00000000009sa','14','Recommendation Letter','Verification','{{employee_name}} - Recommendation Letter',NULL,'[{"kind":"subject","text":"Subject: Letter of Recommendation"},{"kind":"para","text":"To Whomsoever It May Concern,"},{"kind":"para","text":"It is my pleasure to recommend **{{employee_name}}**, who has been associated with **{{company}}**{{exp_designation_clause}}{{exp_department_clause}}."},{"kind":"para","text":"During this association, {{first_name}} has consistently demonstrated professionalism, strong commitment and a collaborative approach. {{first_name}}''s contribution has been valuable to the team and the organization."},{"kind":"para","text":"I am confident that {{first_name}} will be a valuable addition to any organization, and I recommend {{first_name}} without reservation. Please feel free to contact us{{hr_contact_clause}} for any further information."},{"kind":"signature","closing":"Sincerely,"}]',1700000000000,1700000000000),
 ('00000000009sc','15','Relieving Letter','Exit','{{employee_name}} - Relieving Letter',NULL,'[{"kind":"subject","text":"Subject: Relieving Letter"},{"kind":"para","text":"To Whomsoever It May Concern,"},{"kind":"para","text":"This is to certify that **{{employee_name}}**{{rel_role_clause}}, has been relieved of all duties and responsibilities{{tenure_clause}}."},{"kind":"para","text":"At the time of leaving, all dues and company property have been settled and there are no obligations pending against the employee. The employee''s obligations of confidentiality, non-solicitation and assignment of intellectual property survive the cessation of employment."},{"kind":"para","text":"We thank **{{first_name}}** for the contribution during the tenure with us and wish every success in future endeavours."},{"kind":"signature","closing":"For and on behalf of {{company}},"}]',1700000000000,1700000000000);
INSERT INTO letter_templates (uuid,code,label,category,filename,inputs,blocks,created_at,updated_at) VALUES
 ('00000000009se','16','Resignation Acceptance','Exit','{{employee_name}} - Resignation Acceptance',NULL,'[{"kind":"subject","text":"Subject: Acceptance of Resignation"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"This is to acknowledge and accept your resignation from the position of **{{designation}}**{{department_clause}} at **{{company}}**. Your last working day with the organization will be **{{end_date}}**."},{"kind":"para","text":"You are required to serve your notice period, ensure a smooth handover of your responsibilities, and return all Company property on or before your last working day. Your full and final settlement will be processed as per Company policy, subject, to the extent permitted by applicable law, to the Company''s right to recover and set off any amount lawfully due from you. Your obligations of confidentiality, non-solicitation and assignment of intellectual property survive the cessation of your employment."},{"kind":"para","text":"We thank **{{first_name}}** for the contribution during the tenure with us and wish every success in future endeavours."},{"kind":"signature","closing":"For and on behalf of {{company}},"}]',1700000000000,1700000000000),
 ('00000000009sg','17','Full & Final Settlement','Exit','{{employee_name}} - Full and Final Settlement',NULL,'[{"kind":"subject","text":"Subject: Full and Final Settlement"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"para","text":"This letter sets out the full and final settlement of your dues consequent to your separation from **{{company}}**, with your last working day being **{{settlement_date}}**."},{"kind":"para","text":"Your settlement is computed as follows:","requires":"settlement"},{"kind":"computed","ref":"settlement_table","requires":"settlement"},{"kind":"para","text":"The net amount payable to you is **{{settlement_net_words}}**, which will be credited to your registered bank account, subject to applicable statutory deductions, the return of all Company property, and, to the extent permitted by applicable law, the Company''s right to recover and set off any amount lawfully due from you against this settlement.","requires":"settlement"},{"kind":"para","text":"This full and final settlement is issued in complete and final discharge of all dues payable by the Company to you. Your obligations of confidentiality, non-solicitation and assignment of intellectual property, as set out in your Letter of Appointment, survive the termination of your employment. On receipt of the above amount, you confirm that you have no further claim of any nature whatsoever against the Company, its group companies, or their officers and employees. The Company reserves its right to recover any amount subsequently found to be due from you on account of error, overpayment, fraud or misstatement.","requires":"settlement"},{"kind":"para","text":"We thank you for your contribution during your tenure with us and wish you the very best for the future."},{"kind":"signature","closing":"For and on behalf of {{company}},"},{"kind":"gap","height":10},{"kind":"subject","text":"Acknowledgement by the Employee","requires":"settlement"},{"kind":"para","text":"I, **{{legal_name}}**, acknowledge and accept the above full and final settlement in complete satisfaction of all my dues, and confirm that I have no further claim of any nature against **{{company}}**. I agree that my acknowledgement and signature provided by electronic means are valid, binding and enforceable on me.","requires":"settlement"},{"kind":"esignature","label":"Employee Signature","withDate":true,"requires":"settlement"}]',1700000000000,1700000000000),
 ('00000000009sj','18','Experience Certificate','Exit','{{employee_name}} - Experience Certificate',NULL,'[{"kind":"subject","text":"Subject: Experience Certificate"},{"kind":"para","text":"To Whomsoever It May Concern,"},{"kind":"para","text":"This is to certify that **{{employee_name}}** was employed with **{{company}}**{{exp_designation_clause}}{{exp_department_clause}} {{employment_period}}."},{"kind":"para","text":"During the tenure with us, {{first_name}} was found to be sincere, hardworking and professional in conduct. We found the contribution to be valuable."},{"kind":"para","text":"We wish **{{first_name}}** all the best for future endeavours."},{"kind":"signature","closing":"For {{company}},"}]',1700000000000,1700000000000),
 ('00000000009sm','19','Internship Completion Certificate','Exit','{{employee_name}} - Internship Completion Certificate',NULL,'[{"kind":"subject","text":"Subject: Internship Completion Certificate"},{"kind":"para","text":"To Whomsoever It May Concern,"},{"kind":"para","text":"This is to certify that **{{employee_name}}** has successfully completed an internship with **{{company}}**{{exp_designation_clause}}{{exp_department_clause}} {{employment_period}}."},{"kind":"para","text":"During the internship, {{first_name}} was found to be diligent, enthusiastic and quick to learn, and made a positive contribution to the team."},{"kind":"para","text":"We wish **{{first_name}}** all the best for future endeavours."},{"kind":"signature","closing":"For {{company}},"}]',1700000000000,1700000000000),
 ('00000000009sp','20','Other Letter','Other','{{employee_name}} - {{subject}}','[{"key":"subject","label":"Subject","type":"text","required":true,"placeholder":"e.g. Confirmation of Address"},{"key":"body","label":"Letter body","type":"multiline","required":true,"placeholder":"Type the letter content. One paragraph per line; **bold** and {{placeholders}} are supported."}]','[{"kind":"subject","text":"Subject: {{subject}}"},{"kind":"para","text":"Dear {{first_name}},"},{"kind":"input","field":"body"},{"kind":"signature","closing":"For {{company}},"}]',1700000000000,1700000000000);
INSERT INTO automations (uuid,code,name,description,trigger_type,condition_json,actions_json,schedule_json,enabled,disabled,locked,created_at,updated_at) VALUES
 ('0000000001trg','01','Onboard a new hire','When an employee is created: OPEN their onboarding checklist (from the default template, anchored on their start date), AUTO-ENROL them in default benefits, welcome them (citing the checklist + plan count), brief their manager, then wait for onboarding to complete - welcoming them + notifying the manager when it does, or flagging the manager if it isn''t done after 45 days. This is the hire->onboarding hand-off as DATA.','employee.created',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/transitions","body":{"employee":"{{subject}}","kind":"onboarding","template":"default-onboarding","anchor_date":"{{startDate}}"},"captureAs":"onboarding"},{"kind":"apiCall","method":"POST","path":"/v1/{{subject}}:enrollDefaultBenefits","captureAs":"benefits"},{"kind":"notify","recipient":{"of":"subject"},"title":"Welcome aboard!","body":"Your onboarding checklist is ready and you''re enrolled in {{results.benefits.enrolled}} benefit plan(s). Check your tasks to get started.","link":"onboarding"},{"kind":"email","to":{"of":"subject"},"subject":"Welcome aboard!","html":"<p>Welcome to the team! Your onboarding checklist is ready and you''re enrolled in {{results.benefits.enrolled}} benefit plan(s). Log in to see your first-week tasks and get started.</p>"},{"kind":"notifyManager","noun":"new hire - set up their first week"},{"kind":"waitFor","on":[{"event":"transition.completed","match":"employeeId","then":[{"kind":"notify","recipient":{"of":"subject"},"title":"You''re all set!","body":"Your onboarding is complete - welcome aboard.","link":"dashboard"},{"kind":"notifyManager","noun":"onboarding complete for your report"}]},{"timer":{"days":45},"then":[{"kind":"notifyManager","noun":"onboarding still open after 45 days"}]}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001trj','02','Close the requisition when filled','When an offer is accepted for the last opening on a requisition, mark the requisition filled (updates the record via the API).','offer.accepted','{"field":"openings","op":"lte","value":1}','[{"kind":"apiCall","method":"PATCH","path":"/v1/job-requisitions/{{requisitionId}}","body":{"status":"filled"}}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001trm','03','Auto-schedule a screening interview','When an application reaches the interview stage, create a screening interview for it (Recruiting → Interviews).','application.stageChanged','{"field":"stage","op":"eq","value":"interview"}','[{"kind":"apiCall","method":"POST","path":"/v1/interviews","body":{"application":"{{subject}}","title":"Screening interview","mode":"video"}}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001trp','04','Mark onboarding milestone','When an ONBOARDING transition completes, emit the ''employee.onboarded'' milestone that the fan-out rules below react to.','transition.completed','{"field":"kind","op":"eq","value":"onboarding"}','[{"kind":"emitEvent","type":"employee.onboarded"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001trr','05','New hire: set 30-day ramp-up goals','When a new hire finishes onboarding, create a first-30-days ramp-up goal for them (Performance).','employee.onboarded',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/goals","body":{"employee":"employees/{{employeeId}}","title":"Ramp-up: first 30 days","description":"Get set up, meet the team, and land your first contribution."}}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001trt','06','New hire: schedule a 30-day check-in','When a new hire finishes onboarding, open a 30-day check-in with their manager (Performance).','employee.onboarded',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/check-ins","body":{"employee":"employees/{{employeeId}}","notes":"30-day onboarding check-in"}}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001trw','07','Welcome the newest team member','When a new hire finishes onboarding, invite everyone to welcome them (Engagement). Disabled by default (org-wide broadcast).','employee.onboarded',NULL,'[{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"Welcome our newest team member!","body":"A colleague has just completed onboarding - say hello when you get a chance.","link":"employees"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001try','08','Celebrate long-tenure anniversaries','On a 5+ year work anniversary, invite the whole company to celebrate (Engagement). Disabled by default (org-wide broadcast).','schedule.workAnniversary','{"field":"years","op":"gte","value":5}','[{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"A big work anniversary today!","body":"One of our colleagues is celebrating 5+ years with us. Drop them a note!","link":"employees"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001ts0','09','Probation review','When probation is ending (Lifecycle): open a 1:1 check-in for the review (Performance), tell the employee, ask the manager to confirm/extend, and remind the manager after 7 days if still pending.','schedule.probationEnding',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/check-ins","body":{"employee":"employees/{{employeeId}}","notes":"Probation review discussion"}},{"kind":"notify","recipient":{"of":"subject"},"title":"Your probation is ending","body":"Your manager will confirm your status shortly.","link":"profile"},{"kind":"notifyManager","noun":"probation ending - confirm or extend"},{"kind":"email","to":{"of":"managerOf"},"subject":"Action needed: confirm or extend a probation","html":"<p>A team member''s probation period is ending. Please confirm their status or extend probation in the app.</p>"},{"kind":"wait","delayDays":7,"then":[{"kind":"notifyManager","noun":"probation decision still pending"}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ts2','0a','Offboarding wrap-up','When an offboarding transition completes, close the loop with the manager and the departing employee.','transition.completed','{"field":"kind","op":"eq","value":"offboarding"}','[{"kind":"notifyManager","noun":"offboarding completed for your report"},{"kind":"notify","recipient":{"of":"subject"},"title":"Exit formalities complete","body":"Your offboarding is complete. We wish you all the best!","link":"dashboard"},{"kind":"email","to":{"of":"subject"},"subject":"Your exit formalities are complete","html":"<p>Your offboarding is complete and your access will be wound down shortly. Thank you for all your contributions - we wish you the very best.</p>"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ts4','0b','Congratulate work anniversaries','On an employee''s work anniversary, send them a congratulations.','schedule.workAnniversary',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Happy work anniversary!","body":"Thank you for all your contributions. Here''s to many more!","link":"dashboard"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ts6','0c','Celebrate a repaid loan','When a loan is fully repaid (last payroll installment), let the employee know.','loan.closed',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Your loan is fully repaid","body":"The final installment was deducted in this payroll run. You''re all paid up!","link":"loans"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ts8','0d','Remind owners of expiring documents','When a personal document is within 30 days of expiry, remind its owner (in-app) to renew it.','document.expiring','{"field":"daysLeft","op":"lte","value":30}','[{"kind":"notify","recipient":{"of":"subject"},"title":"A document is expiring soon","body":"Your document \"{{title}}\" expires in {{daysLeft}} day(s). Please renew it.","link":"documents"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tsa','0e','Thank suggestion authors','When someone submits a (non-anonymous) suggestion, thank them and point to where they can track it.','suggestion.submitted','{"field":"anonymous","op":"eq","value":false}','[{"kind":"notify","recipient":{"of":"subject"},"title":"Thanks for your suggestion!","body":"HR will review it. You can track its status on the Suggestions page.","link":"suggestions"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tsc','0f','High-value reimbursement SLA','For a claim over 25,000: wait for a decision; if none within 2 days, nudge the approving manager. The approve/reject branch cancels the timer. Disabled by default (opt-in; tune the threshold).','reimbursement.submitted','{"field":"amount","op":"gt","value":25000}','[{"kind":"waitFor","on":[{"event":"reimbursement.approved","match":"subject","then":[{"kind":"notifyManager","noun":"high-value reimbursement resolved"}]},{"event":"reimbursement.rejected","match":"subject","then":[{"kind":"notifyManager","noun":"high-value reimbursement resolved"}]},{"timer":{"days":2},"then":[{"kind":"notifyManager","noun":"high-value reimbursement pending 2+ days"},{"kind":"email","to":{"of":"managerOf"},"subject":"A high-value reimbursement has been pending 2+ days","html":"<p>A high-value reimbursement claim from one of your reports has been awaiting a decision for over two days. Please review it in your Approvals inbox.</p>"}]}]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tse','0g','Escalate high-priority tickets','When a high-priority ticket is raised, alert the requester''s manager. Disabled by default (opt-in).','ticket.created','{"field":"priority","op":"eq","value":"high"}','[{"kind":"notifyManager","noun":"high-priority support ticket raised by your report"},{"kind":"email","to":{"of":"managerOf"},"subject":"High-priority support ticket from your report","html":"<p>One of your reports raised a high-priority support ticket. Please make sure it''s being picked up.</p>"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tsg','0h','Support SLA reminder','When a ticket is raised, wait for it to be resolved; if it isn''t within 3 days, nudge the requester. Disabled by default (opt-in). Durable: the resolve cancels the timer.','ticket.created',NULL,'[{"kind":"waitFor","on":[{"event":"ticket.resolved","match":"subject","then":[{"kind":"notify","recipient":{"of":"subject"},"title":"Your ticket was resolved","body":"Thanks for your patience.","link":"tickets"}]},{"timer":{"days":3},"then":[{"kind":"notify","recipient":{"of":"subject"},"title":"Still working on your ticket","body":"This is taking a little longer than usual - we''re on it.","link":"tickets"}]}]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tsj','0i','Policy acknowledgement reminder','When a policy document that requires acknowledgement is published, remind everyone after 7 days. Disabled by default (opt-in; can be noisy).','document.published','{"field":"requiresAck","op":"eq","value":true}','[{"kind":"wait","delayDays":7,"then":[{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"Please acknowledge the recent policy","body":"A policy published last week still needs your acknowledgement.","link":"documents"}]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tsm','0j','Sync new hires to an external system','Example: POST new-hire basics to an external HRIS/provisioning webhook. Disabled by default and inert until an operator configures webhook egress (the WebhookSender port + a destination allowlist).','employee.created',NULL,'[{"kind":"webhook","url":"https://example.invalid/hooks/new-hire","includeFields":["departmentId","startDate"]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tsp','0k','Provision IT & workspace for new hires','When an employee is created: raise an IT provisioning ticket and a facilities (desk + access card) ticket for the new hire (Support), let them know, and brief their manager. Bridges Lifecycle -> Support.','employee.created',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/tickets","body":{"employee":"{{subject}}","category":"it","subject":"Provision accounts for a new hire","description":"Create email, SSO, and tool access before the start date.","priority":"high","initial_todos":["Email + SSO","Laptop","Software licenses"]}},{"kind":"apiCall","method":"POST","path":"/v1/tickets","body":{"employee":"{{subject}}","category":"facilities","subject":"Desk & access card for a new hire","description":"Assign a desk and issue a building access card.","priority":"medium","initial_todos":["Desk","Access card"]}},{"kind":"notify","recipient":{"of":"subject"},"title":"We''re setting up your workspace","body":"IT access and your desk are being arranged - they''ll be ready for your first day.","link":"tickets"},{"kind":"notifyManager","noun":"new hire - IT & facilities requests raised"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tsr','0l','Introduce a new hire to their department','When an employee is created, post a welcome to their department''s members (Engagement) - scoped to the immediate team via the event''s department, not the whole company. Disabled by default (opt-in broadcast).','employee.created',NULL,'[{"kind":"notifyAudience","audience":{"kind":"department","department":"{{departmentId}}"},"title":"A new teammate is joining!","body":"Please give a warm welcome to the newest member of your team.","link":"employees"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tst','0m','Raise the first-week milestone','Seven days after a hire finishes onboarding, emit the ''first week'' milestone the rules below react to (Lifecycle). A delayed fan-out (wait -> emitEvent).','employee.onboarded',NULL,'[{"kind":"wait","delayDays":7,"then":[{"kind":"emitEvent","type":"milestone.firstWeek"}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tsw','0n','First week: nudge the manager for feedback','At a new hire''s first-week milestone, ask their manager for early feedback (Performance).','milestone.firstWeek',NULL,'[{"kind":"notifyManager","noun":"new hire''s first week - share early feedback"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tsy','0o','First week: open a settling-in check-in','At a new hire''s first-week milestone, open a settling-in 1:1 with the employee (Performance).','milestone.firstWeek',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/check-ins","body":{"employee":"employees/{{employeeId}}","notes":"First-week settling-in check-in"}}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tt0','0p','Track loan disbursement','When a loan is approved: confirm the EMI to the employee, then wait for disbursement - confirming it when it happens, or flagging the manager if it hasn''t disbursed within 5 days (Payroll). Durable.','loan.approved',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Your loan is approved","body":"Your monthly EMI will be {{emiAmount}}. We''ll disburse the loan shortly.","link":"loans"},{"kind":"waitFor","on":[{"event":"loan.disbursed","match":"employeeId","then":[{"kind":"notify","recipient":{"of":"subject"},"title":"Your loan has been disbursed","body":"The approved amount of {{amount}} has been disbursed.","link":"loans"}]},{"timer":{"days":5},"then":[{"kind":"notifyManager","noun":"approved loan not disbursed after 5 days"}]}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tt2','0q','Track a referral bonus to payout','When a referral bonus is awarded: tell the referrer, then wait for it to be paid in payroll - confirming the payout, or nudging after 60 days if it hasn''t been paid (Recruiting -> Payroll). Durable.','referral.awarded',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Your referral bonus is approved","body":"A referral bonus of {{amount}} has been awarded and will be paid in an upcoming payroll run.","link":"referrals"},{"kind":"waitFor","on":[{"event":"referral.paid","match":"employeeId","then":[{"kind":"notify","recipient":{"of":"subject"},"title":"Your referral bonus was paid","body":"Your {{amount}} referral bonus was included in this payroll run.","link":"payslips"}]},{"timer":{"days":60},"then":[{"kind":"notifyManager","noun":"referral bonus still unpaid after 60 days"}]}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tt4','0r','Reward milestone work anniversaries','On a 3+ year work anniversary: award a loyalty bonus (Payroll, paid next run, stamped {{today}}), thank the employee, and invite the company to celebrate (Engagement). Disabled by default (money + broadcast).','schedule.workAnniversary','{"field":"years","op":"gte","value":3}','[{"kind":"apiCall","method":"POST","path":"/v1/bonuses:award","body":{"scope":"individual","employee":"employees/{{employeeId}}","amount":5000,"kind":"loyalty","reason":"{{years}}-year work anniversary","award_date":"{{today}}"}},{"kind":"notify","recipient":{"of":"subject"},"title":"Thank you for {{years}} years!","body":"We''ve added a loyalty bonus to your next payslip in appreciation of your time with us.","link":"payslips"},{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"Celebrating a big milestone!","body":"A colleague is marking {{years}} years with us today - drop them a note of congratulations.","link":"employees"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tt6','0s','Offboarding: deprovision, farewell & sync','When an offboarding completes: raise an IT deprovisioning ticket for the leaver (Support), post a farewell to the company (Engagement), and notify an external HRIS via webhook. Disabled by default (broadcast + needs webhook egress configured).','transition.completed','{"field":"kind","op":"eq","value":"offboarding"}','[{"kind":"apiCall","method":"POST","path":"/v1/tickets","body":{"employee":"employees/{{employeeId}}","category":"it","subject":"Deprovision a departing employee","description":"Revoke SSO/email/tool access and reclaim company assets.","priority":"high","initial_todos":["Revoke SSO & email","Reclaim laptop","Reclaim access card"]}},{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"Farewell to a colleague","body":"A teammate is moving on - thank them for their contributions and wish them well.","link":"employees"},{"kind":"webhook","url":"https://example.invalid/hooks/offboard","includeFields":["kind"]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tt8','0t','Leave decision SLA','When leave is requested, wait for the decision; if none within 2 days, nudge the approving manager (the approve/reject cancels the timer).','leave.requested',NULL,'[{"kind":"waitFor","on":[{"event":"leave.approved","match":"subject","then":[{"kind":"notifyManager","noun":"leave request resolved"}]},{"event":"leave.rejected","match":"subject","then":[{"kind":"notifyManager","noun":"leave request resolved"}]},{"timer":{"days":2},"then":[{"kind":"notifyManager","noun":"leave request awaiting your decision for 2+ days"},{"kind":"email","to":{"of":"managerOf"},"subject":"A leave request has been waiting 2+ days","html":"<p>A leave request from one of your reports has been awaiting your decision for over two days. Please review it in your Approvals inbox.</p>"}]}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tta','0u','Extended leave: arrange coverage','When a leave of 5+ days is approved, remind the manager to arrange coverage for the team.','leave.approved','{"field":"days","op":"gte","value":5}','[{"kind":"notifyManager","noun":"extended leave approved - arrange coverage"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ttc','0v','Leave cancelled: free the calendar','When an employee cancels approved/pending leave, let their manager know the dates are freed up.','leave.cancelled',NULL,'[{"kind":"notifyManager","noun":"report cancelled their leave"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tte','0w','Acknowledge an encashment request','When an employee requests leave encashment, confirm it was received and is pending HR review.','leaveEncashment.requested',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Encashment request received","body":"Your request to encash {{days}} day(s) has been submitted - HR will review it.","link":"leave-requests/encashments"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ttg','0x','Confirm an approved encashment','When leave encashment is approved, tell the employee it will be paid in an upcoming payroll run.','leaveEncashment.approved',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Encashment approved","body":"Your encashment of {{days}} day(s) ({{amount}}) will be paid in an upcoming payroll run.","link":"payslips"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ttj','0y','Overtime decision SLA','When overtime is requested, nudge the manager if it isn''t approved within 2 days. Durable.','overtime.requested',NULL,'[{"kind":"waitFor","on":[{"event":"overtime.approved","match":"subject","then":[{"kind":"notifyManager","noun":"overtime request resolved"}]},{"timer":{"days":2},"then":[{"kind":"notifyManager","noun":"overtime request awaiting approval for 2+ days"},{"kind":"email","to":{"of":"managerOf"},"subject":"An overtime request needs your decision","html":"<p>An overtime request from one of your reports has been waiting over two days. Please approve or decline it in your Approvals inbox.</p>"}]}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ttm','0z','Confirm approved overtime','When overtime is approved, confirm to the employee that it will be paid as a taxable earning in the next run.','overtime.approved',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Overtime approved","body":"Your {{hours}} hour(s) of overtime were approved and will be paid in your next payroll run.","link":"overtime/history"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ttp','10','Remote-work decision SLA','When remote work is requested, nudge the manager if it isn''t decided within 2 days. Durable.','remoteWork.requested',NULL,'[{"kind":"waitFor","on":[{"event":"remoteWork.approved","match":"subject","then":[{"kind":"notifyManager","noun":"remote-work request resolved"}]},{"timer":{"days":2},"then":[{"kind":"notifyManager","noun":"remote-work request awaiting your decision"},{"kind":"email","to":{"of":"managerOf"},"subject":"A remote-work request needs your decision","html":"<p>A remote-work request from one of your reports has been waiting over two days. Please review it in your Approvals inbox.</p>"}]}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ttr','11','Regularization decision SLA','When an attendance regularization is requested, nudge the manager if it isn''t decided within 3 days. Durable.','attendanceRegularization.requested',NULL,'[{"kind":"waitFor","on":[{"event":"attendanceRegularization.approved","match":"subject","then":[{"kind":"notifyManager","noun":"regularization resolved"}]},{"timer":{"days":3},"then":[{"kind":"notifyManager","noun":"attendance regularization awaiting your decision"},{"kind":"email","to":{"of":"managerOf"},"subject":"An attendance regularization needs your decision","html":"<p>An attendance regularization from one of your reports has been waiting over three days. Please review it in your Approvals inbox.</p>"}]}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001ttt','12','Payday announcement','When a payroll run is published, announce to the company that payslips are available. Disabled by default (org-wide broadcast).','payroll.published',NULL,'[{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"Payslips are ready","body":"Payslips for this pay cycle have been published - view yours in Payslips.","link":"payslips"},{"kind":"emailAudience","audience":{"kind":"everyone"},"subject":"Your payslip is ready","html":"<p>Payslips for this pay cycle have been published. Log in to view yours under Payslips.</p>"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001ttw','13','Email each employee their payslip','When a payslip is published (one event per employee), email that employee their payslip PDF as an attachment. Disabled by default (a payslip is sensitive PII leaving over email; enable once your email provider is configured and this is a deliberate policy). Showcases an email attachment referencing the event''s payslip.','payslip.published',NULL,'[{"kind":"email","to":{"of":"subject"},"subject":"Your payslip is ready","html":"<p>Your payslip for this pay period is attached. You can also view it any time under Payslips.</p>","attachments":[{"document":"{{subject}}","filename":"Payslip.pdf"}]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tty','14','Email finance the payroll bank file','When a payroll run is published, email the bank-transfer file to finance as an attachment. Disabled by default - set your finance address and the bank format slug, then enable. Showcases an address recipient (not an employee) plus a generated (bankFile) attachment.','payroll.published',NULL,'[{"kind":"email","to":{"of":"address","address":"finance@example.com"},"subject":"Payroll bank file for the latest run","html":"<p>The bank-transfer file for the latest published payroll run is attached. Upload it to your bank portal to disburse salaries.</p>","attachments":[{"bankFile":{"run":"{{subject}}","bank":"your-bank-format"},"filename":"payroll-bank-file.xlsx"}]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tv0','15','Reimbursement approved: assure payout','When a reimbursement claim is approved, tell the employee it will be paid in an upcoming run.','reimbursement.approved',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Reimbursement approved","body":"Your claim for {{amount}} was approved and will be paid in an upcoming payroll run.","link":"reimbursements/history"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tv2','16','Reimbursement rejected: next steps','When a reimbursement claim is rejected, point the employee at what to do next.','reimbursement.rejected',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Reimbursement not approved","body":"Your claim for {{amount}} wasn''t approved. Check the notes, then reach out to finance or resubmit with the right details.","link":"reimbursements/history"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tv4','17','Track a reimbursement to payout','When a claim is approved, wait for it to be paid; if it hasn''t been within 14 days, reassure the employee it''s still processing. Disabled by default. Durable.','reimbursement.approved',NULL,'[{"kind":"waitFor","on":[{"event":"reimbursement.paid","match":"subject","then":[{"kind":"notify","recipient":{"of":"subject"},"title":"Reimbursement paid","body":"Your approved claim has been paid.","link":"reimbursements/history"}]},{"timer":{"days":14},"then":[{"kind":"notify","recipient":{"of":"subject"},"title":"Your reimbursement is still processing","body":"Your approved claim hasn''t been paid yet - it will be included in an upcoming run.","link":"reimbursements/history"}]}]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tv6','18','Loan request SLA','When a loan/advance is requested, wait for the decision; if none within 3 days, nudge the approving manager. Durable.','loan.requested',NULL,'[{"kind":"waitFor","on":[{"event":"loan.approved","match":"subject","then":[{"kind":"notifyManager","noun":"loan request resolved"}]},{"event":"loan.rejected","match":"subject","then":[{"kind":"notifyManager","noun":"loan request resolved"}]},{"timer":{"days":3},"then":[{"kind":"notifyManager","noun":"loan request awaiting your decision for 3+ days"},{"kind":"email","to":{"of":"managerOf"},"subject":"A loan/advance request needs your decision","html":"<p>A loan/advance request from one of your reports has been awaiting your decision for over three days. Please review it in your Approvals inbox.</p>"}]}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tv8','19','Loan rejected: guidance','When a loan/advance is not approved, let the employee know HR can talk through the options.','loan.rejected',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Your request wasn''t approved","body":"Your loan/advance request wasn''t approved this time. HR can walk you through the eligibility and alternatives.","link":"loans"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tva','1a','Loan repayment progress','After each payroll installment, tell the employee the remaining balance. Disabled by default (one message per run can be noisy).','loan.repaymentRecorded',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Loan installment recorded","body":"This run''s installment of {{amount}} was deducted. Remaining balance: {{outstanding}}.","link":"loans"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tvc','1b','Anniversary: nudge the manager to recognize','On an employee''s work anniversary, prompt their manager to send a note of appreciation.','schedule.workAnniversary',NULL,'[{"kind":"notifyManager","noun":"report''s work anniversary today - send a note"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tve','1c','New hire: assign security & compliance training','When a new hire finishes onboarding, create a goal to complete security & compliance training (Performance).','employee.onboarded',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/goals","body":{"employee":"employees/{{employeeId}}","title":"Complete security & compliance training","description":"Finish the mandatory security and workplace-conduct modules in your first weeks."}}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tvg','1d','New hire: schedule a 90-day review','When a new hire finishes onboarding, open a 90-day review check-in with their manager after 90 days (wait -> create).','employee.onboarded',NULL,'[{"kind":"wait","delayDays":90,"then":[{"kind":"apiCall","method":"POST","path":"/v1/check-ins","body":{"employee":"employees/{{employeeId}}","notes":"90-day review check-in"}}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tvj','1e','First week: share the handbook','At a new hire''s first-week milestone, point them to the employee handbook and policies.','milestone.firstWeek',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Get to know how we work","body":"Take some time this week to read the employee handbook and company policies.","link":"documents"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tvm','1f','New policy: prompt acknowledgement','When a policy that requires acknowledgement is published, prompt everyone to review & sign it now. Disabled by default (org-wide broadcast; the 7-day reminder is separate).','document.published','{"field":"requiresAck","op":"eq","value":true}','[{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"A new policy needs your acknowledgement","body":"A policy was just published that requires your review and signature.","link":"documents"},{"kind":"emailAudience","audience":{"kind":"everyone"},"subject":"A new policy needs your acknowledgement","html":"<p>A new policy was just published that requires your review and signature. Please log in to read and acknowledge it.</p>"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tvp','1g','Ticket resolved: ask for feedback','When a support ticket is resolved, invite the requester to confirm it''s fixed and share feedback.','ticket.resolved',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"Your ticket was resolved","body":"We''ve marked your ticket resolved. If it''s not fully sorted, reopen it or reply - and tell us how we did.","link":"tickets"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tvr','1h','Open a renewal task for an expiring document','When a personal document is within 15 days of expiry, open an HR ticket for the owner to upload the renewed copy, then confirm the task to them. Bridges Compliance -> Support.','document.expiring','{"field":"daysLeft","op":"lte","value":15}','[{"kind":"apiCall","method":"POST","path":"/v1/tickets","body":{"employee":"employees/{{employeeId}}","category":"hr","subject":"Renew an expiring document","description":"Your document \"{{title}}\" expires in {{daysLeft}} day(s). Please upload the renewed copy.","priority":"medium"},"captureAs":"renewalTicket"},{"kind":"notify","recipient":{"of":"subject"},"title":"We''ve opened a renewal task","body":"\"{{results.renewalTicket.subject}}\" is on your tickets - please upload the renewed document before it expires.","link":"tickets"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tvt','1i','Plan coverage for extended leave','When 10+ days of leave are approved: brief the manager and open a coverage/handover task for the employee. Bridges Leave -> Support. Disabled by default.','leave.approved','{"field":"days","op":"gte","value":10}','[{"kind":"notifyManager","noun":"extended leave approved - plan coverage & handover"},{"kind":"apiCall","method":"POST","path":"/v1/tickets","body":{"employee":"employees/{{employeeId}}","category":"general","subject":"Coverage & handover for extended leave","description":"{{days}} day(s) of leave approved. Note who covers what and hand over in-flight work.","priority":"medium"}}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tvw','1j','Fulfil a work-anniversary gift','On a work anniversary, open a facilities task to send a small gift/token. Bridges Lifecycle -> Support. Disabled by default.','schedule.workAnniversary','{"field":"years","op":"gte","value":1}','[{"kind":"apiCall","method":"POST","path":"/v1/tickets","body":{"employee":"employees/{{employeeId}}","category":"facilities","subject":"Send a work-anniversary gift","description":"{{years}}-year anniversary - arrange a small gift or token of appreciation.","priority":"low"}}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tvy','1k','Triage a suggestion into an HR ticket','When a non-anonymous suggestion is submitted, open an HR ticket to review and respond. Bridges Engagement -> Support. Disabled by default (anonymity-safe: anonymous ones are skipped).','suggestion.submitted','{"field":"anonymous","op":"eq","value":false}','[{"kind":"apiCall","method":"POST","path":"/v1/tickets","body":{"employee":"employees/{{employeeId}}","category":"hr","subject":"Review an employee suggestion","description":"A suggestion was submitted for review - triage it and respond via the Suggestions page.","priority":"low"}}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tw0','1l','Raise the 30-day milestone','Thirty days after a hire finishes onboarding, emit the ''first month'' milestone the rules below react to (Lifecycle). Delayed fan-out (wait -> emitEvent).','employee.onboarded',NULL,'[{"kind":"wait","delayDays":30,"then":[{"kind":"emitEvent","type":"milestone.thirtyDays"}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tw2','1m','First month: manager review touchpoint','At a new hire''s 30-day milestone, prompt their manager for a first-month review (Performance).','milestone.thirtyDays',NULL,'[{"kind":"notifyManager","noun":"new hire''s first month - do a quick review"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tw4','1n','First month: employee pulse','At a new hire''s 30-day milestone, invite them to share how their first month has gone (Performance).','milestone.thirtyDays',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"How''s your first month going?","body":"You''re 30 days in - share what''s working and what you need with your manager.","link":"check-ins"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tw6','1o','New hire ramp watch','From onboarding, wait for the 30-day milestone to celebrate one month in; if it hasn''t fired within 45 days, nudge the manager to check on ramp-up. Durable; links to the milestone fan-out.','employee.onboarded',NULL,'[{"kind":"waitFor","on":[{"event":"milestone.thirtyDays","match":"employeeId","then":[{"kind":"notify","recipient":{"of":"subject"},"title":"One month in - nice work!","body":"You''ve completed your first month. Keep going!","link":"dashboard"}]},{"timer":{"days":45},"then":[{"kind":"notifyManager","noun":"new hire ramp-up - check in if it''s lagging"}]}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001tw8','1p','Ticket CSAT follow-up','Two days after a ticket is resolved, follow up so the requester can confirm it stayed fixed and rate the experience (Support). Uses a delay.','ticket.resolved',NULL,'[{"kind":"wait","delayDays":2,"then":[{"kind":"notify","recipient":{"of":"subject"},"title":"Did that fix it?","body":"It''s been a couple of days since we resolved your ticket - reopen it if anything''s still off, and let us know how we did.","link":"tickets"}]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001twa','1q','Sync approved leave to an external calendar','When leave is approved, POST the dates to an external calendar/HRIS webhook. Disabled by default and inert until webhook egress is configured.','leave.approved',NULL,'[{"kind":"webhook","url":"https://example.invalid/hooks/leave-approved","includeFields":["from","to","days"]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001twc','1r','Offboarding: compute F&F settlement + exit clearance','When an offboarding completes: compute and store the full-and-final settlement (Payroll), then open an exit-clearance ticket for the employee that references it. Disabled by default (F&F is usually HR-reviewed).','transition.completed','{"field":"kind","op":"eq","value":"offboarding"}','[{"kind":"apiCall","method":"POST","path":"/v1/settlements","body":{"employee":"employees/{{employeeId}}"},"captureAs":"settlement"},{"kind":"apiCall","method":"POST","path":"/v1/tickets","body":{"employee":"employees/{{employeeId}}","category":"hr","subject":"Exit clearance & asset return","description":"Complete exit clearance and reclaim assets. Full-and-final settlement draft: {{results.settlement.path}}.","priority":"high"}}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001twe','1s','Seed a triage checklist on IT tickets','When an IT support ticket is raised, append the standard triage checklist so nothing is missed. Bridges into Support workflow (a real record change, not a message).','ticket.created','{"field":"category","op":"eq","value":"it"}','[{"kind":"apiCall","method":"POST","path":"/v1/{{subject}}:addTodos","body":{"texts":["Acknowledge & triage","Reproduce / confirm the issue","Resolve & verify the fix","Confirm with the requester"]}}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001twg','1t','Auto-approve small salary advances','When a loan/advance of 10,000 or less is requested, approve it automatically (Payroll). Disabled by default (moves money with no human decision; set your own cap).','loan.requested','{"field":"amount","op":"lte","value":10000}','[{"kind":"apiCall","method":"POST","path":"/v1/{{subject}}:approve"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001twj','1u','Open the statutory filing after each run','When a payroll run is published, create a compliance event to remit statutory dues (PF/ESI/TDS) for that period. Bridges Payroll -> Compliance. Disabled by default (tune the due date).','payroll.published',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/compliance-events","body":{"title":"Remit statutory dues for the latest pay run","category":"payroll","frequency":"one_time","due_date":"{{today}}"}}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001twm','1v','Initiate a new hire''s background check','When an employee is created, open an identity background-check record to start verification (Compliance). Bridges Lifecycle -> Compliance. Disabled by default.','employee.created',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/background-checks","body":{"employee":"{{subject}}","check_type":"identity"}}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001twp','1w','New hire: complete-your-profile goal','When an employee is created, create a goal prompting them to complete their profile (bank, identity, personal details, documents). Bridges Lifecycle -> Performance.','employee.created',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/goals","body":{"employee":"{{subject}}","title":"Complete your employee profile","description":"Add your bank, identity and personal details and upload any required documents in your first week."}}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001twr','1x','Open a probation confirmation task','When probation is ending, open an HR ticket to confirm or extend it, so the decision is tracked (not just a reminder). Bridges Lifecycle -> Support.','schedule.probationEnding',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/tickets","body":{"employee":"employees/{{employeeId}}","category":"hr","subject":"Confirm or extend probation","description":"Probation ends {{probationEndDate}}. Confirm the employee or extend probation, then update their record.","priority":"medium"}}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001twt','1y','Auto-approve small reimbursements','When a reimbursement of 2,000 or less is submitted, approve it automatically (Payroll). Disabled by default (no human decision; tune the cap).','reimbursement.submitted','{"field":"amount","op":"lte","value":2000}','[{"kind":"apiCall","method":"POST","path":"/v1/{{subject}}:approve"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tww','1z','Auto-disburse approved advances','When a loan/advance is approved, disburse it automatically (Payroll). Disabled by default (auto money movement; enable if finance wants approval to release funds).','loan.approved',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/{{subject}}:disburse"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001twy','20','Auto-approve single-day leave','When a leave request of 1 day or less is made, approve it automatically (Leave). Disabled by default (bypasses the manager''s decision; the balance check still applies).','leave.requested','{"field":"days","op":"lte","value":1}','[{"kind":"apiCall","method":"POST","path":"/v1/{{subject}}:approve"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tx0','21','Assign a laptop to new hires','When an employee is created, add a ''Company laptop'' asset assigned to them so it shows in IT inventory. Bridges Lifecycle -> Assets. Disabled by default (IT sets the real tag/model).','employee.created',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/assets","body":{"name":"Company laptop","category":"IT hardware","status":"assigned","assigned_to":"{{subject}}"}}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001tx2','22','Monday: nudge managers with pending approvals','Every Monday, remind each manager who has requests waiting on their decision to clear their Approvals inbox. Skips managers with an empty queue.','schedule.recurring','{"field":"pendingApprovals","op":"gte","value":1}','[{"kind":"notify","recipient":{"of":"subject"},"title":"You have approvals waiting","body":"There are {{pendingApprovals}} request(s) awaiting your decision. Clear them from your Approvals inbox.","link":"approvals"}]','{"freq":"weekly","day":1,"scope":"perEmployee"}',1,0,0,1700000000000,1700000000000),
 ('0000000001tx4','23','Monday: email managers with pending approvals','Every Monday, email each manager who has requests waiting on their decision. Off by default - enable once email is configured.','schedule.recurring','{"field":"pendingApprovals","op":"gte","value":1}','[{"kind":"email","to":{"of":"subject"},"subject":"You have {{pendingApprovals}} approval(s) waiting","html":"<p>You have <strong>{{pendingApprovals}}</strong> request(s) awaiting your decision. Please clear them from your Approvals inbox.</p>"}]','{"freq":"weekly","day":1,"scope":"perEmployee"}',0,0,0,1700000000000,1700000000000),
 ('0000000001tx6','24','Quarterly: nudge people overdue for a break','On the 1st of each quarter-ish month, gently remind anyone who hasn''t taken leave in over ~6 months (and has balance to spare) to plan some time off.','schedule.recurring','{"all":[{"field":"daysSinceLastLeave","op":"gte","value":180},{"field":"leaveBalanceDays","op":"gte","value":5}]}','[{"kind":"notify","recipient":{"of":"subject"},"title":"Due for a break?","body":"You haven''t taken leave in a while and have {{leaveBalanceDays}} days in balance. Consider planning some time off."}]','{"freq":"monthly","day":1,"scope":"perEmployee"}',0,0,0,1700000000000,1700000000000),
 ('0000000001tx8','25','Monday: nudge owners of goals due soon','Every Monday, remind each employee who has open goals due within the next 7 days to push them over the line (or move the date).','schedule.recurring','{"field":"goalsDueSoon","op":"gte","value":1}','[{"kind":"notify","recipient":{"of":"subject"},"title":"Goals due this week","body":"You have {{goalsDueSoon}} goal(s) due within a week. Update progress or adjust the due date.","link":"goals"}]','{"freq":"weekly","day":1,"scope":"perEmployee"}',1,0,0,1700000000000,1700000000000),
 ('0000000001txa','26','Monday: chase overdue goals','Every Monday, remind each employee with overdue goals to update or reschedule them, and let their manager know so it can come up in a 1:1.','schedule.recurring','{"field":"goalsOverdue","op":"gte","value":1}','[{"kind":"notify","recipient":{"of":"subject"},"title":"Overdue goals","body":"You have {{goalsOverdue}} overdue goal(s). Update progress, push the due date, or close them out.","link":"goals"},{"kind":"notifyManager","noun":"report has overdue goals"}]','{"freq":"weekly","day":1,"scope":"perEmployee"}',1,0,0,1700000000000,1700000000000),
 ('0000000001txc','27','Month start: payroll prep reminder','On the 1st of every month, remind the team to review inputs and build the month''s payroll run. Disabled by default (turn on and point the audience at your finance team).','schedule.recurring',NULL,'[{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"Payroll prep for this month","body":"Time to review income inputs (reimbursements, overtime, loans) and build this month''s payroll run."}]','{"freq":"monthly","day":1,"scope":"once"}',0,0,0,1700000000000,1700000000000),
 ('0000000001txe','28','Kanban: chase blocked cards','When a card is marked blocked, alert the owner''s manager. If it''s still blocking work two days later, remind them again.','card.blocked',NULL,'[{"kind":"notifyManager","noun":"blocked card - clear the blocker"},{"kind":"wait","delayDays":2,"then":[{"kind":"notifyManager","noun":"card STILL blocked after 2 days"}]}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001txg','29','Goal completed: celebrate the achiever','When someone marks a goal complete, send them a congratulations. (Their manager is notified separately.)','goal.completed',NULL,'[{"kind":"notify","recipient":{"of":"subject"},"title":"🎯 Goal complete!","body":"Nice work finishing a goal. It''s logged against your performance record.","link":"goals"}]',NULL,1,0,0,1700000000000,1700000000000),
 ('0000000001txj','2a','Sprint started: rally the board','Announce a new sprint to everyone so the team knows work has started.','sprint.started',NULL,'[{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"🏁 Sprint started","body":"{{name}} is underway. Pull your committed cards and get going.","link":"boards"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001txm','2b','Sprint completed: schedule a retro','On sprint completion, drop an all-day retrospective onto the calendar and let the team know to reflect.','sprint.completed',NULL,'[{"kind":"apiCall","method":"POST","path":"/v1/events","body":{"title":"Retro: {{name}}","start_time":"{{today}}","end_time":"{{today}}","all_day":true,"count_as_work":true}},{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"🔁 Sprint wrapped","body":"{{name}} is done - a retrospective has been added to the calendar. Bring your learnings.","link":"events"}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001txp','2c','Leave approved: sync to external calendar','POST approved leave to an external calendar or HRIS webhook so out-of-office shows up everywhere. Configure the URL and enable to use.','leave.approved',NULL,'[{"kind":"webhook","url":"https://example.com/hooks/leave-approved","includeFields":["employeeId","subject"]}]',NULL,0,0,0,1700000000000,1700000000000),
 ('0000000001txr','2d','Friday: submit your timesheets','Every Friday, remind everyone to log their hours before the week closes.','schedule.recurring',NULL,'[{"kind":"notifyAudience","audience":{"kind":"everyone"},"title":"🕒 Log your time","body":"It''s Friday - please submit your timesheets for the week so approvals aren''t held up."}]','{"freq":"weekly","day":5,"scope":"once"}',0,0,0,1700000000000,1700000000000);
